// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [enhanceSlideboxRange(input), enhanceSlideboxRangeFill(input)],
);

(function (demo, signal) {
  const button = demo.querySelector("[data-night]");
  button.addEventListener(
    "click",
    () => {
      const night = demo.toggleAttribute("data-night");
      button.setAttribute("aria-pressed", String(night));
      button.textContent = night ? "Switch to day" : "Switch to night";
      demo.querySelector("[data-temperature]").textContent = night
        ? "18°"
        : "24°";
      demo.querySelector("[data-condition]").textContent = night
        ? "Clear skies"
        : "Golden hour";
    },
    { signal },
  );
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
